effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec2 uv = acScreenNorm;
    float t = acTime;
    float line = uv.y*acScreenSize.y;
    float wob = sin(uv.y*8.0 + t*2.0)*0.002 + sin(uv.y*60.0 + t*10.0)*0.0008;
    uv.x += wob * distort * 4.0;
    float bl = bleed*0.008;
    float r = texture2DCv(inputImg.texture, uv+vec2(bl,0.0)).r;
    vec4 g = texture2DCv(inputImg.texture, uv);
    float b = texture2DCv(inputImg.texture, uv-vec2(bl,0.0)).b;
    vec4 col = vec4(r,g.g,b,g.a);
    float n = rand(vec2(floor(line), floor(t*30.0)))*noise*0.35;
    col.rgb += n*col.a;
    float sl = (sin(line*3.14159)*0.5+0.5);
    col.rgb *= 1.0 - sl*scanline*0.5;
    gl_FragColor = col;
}
